import { useDraggable, useDropLine } from '@platejs/dnd';
import { GripVertical } from 'lucide-react';
import { KEYS } from 'platejs';
import type { PlateElementProps, RenderNodeWrapper } from 'platejs/react';
import { MemoizedChildren } from 'platejs/react';
import type { ReactElement } from 'react';
import { cn } from '@/lib/utils';

const UNDRAGGABLE: string[] = [KEYS.tr, KEYS.td, KEYS.th, KEYS.codeLine];

function DropLine(): ReactElement | null {
    const { dropLine } = useDropLine();

    if (!dropLine) {
        return null;
    }

    return (
        <div
            className={cn(
                'absolute inset-x-0 h-0.5 bg-ring',
                dropLine === 'top' ? '-top-px' : '-bottom-px',
            )}
            contentEditable={false}
        />
    );
}

function Draggable({ children, element }: PlateElementProps): ReactElement {
    const { isDragging, nodeRef, handleRef } = useDraggable({ element });

    return (
        <div className={cn('group relative', isDragging && 'opacity-50')}>
            <div
                className="absolute top-0 -left-8 hidden h-full select-none opacity-0 transition-opacity group-hover:opacity-100 sm:flex"
                contentEditable={false}
            >
                <button
                    aria-label="Перетащить блок"
                    className="mt-1 flex h-6 w-5 cursor-grab items-center justify-center rounded-md text-muted-foreground hover:bg-accent active:cursor-grabbing"
                    data-plate-prevent-deselect
                    ref={handleRef}
                    type="button"
                >
                    <GripVertical className="size-4" />
                </button>
            </div>
            <div className="flow-root" ref={nodeRef}>
                <MemoizedChildren>{children}</MemoizedChildren>
                <DropLine />
            </div>
        </div>
    );
}

export const BlockDraggable: RenderNodeWrapper = ({
    editor,
    element,
    path,
}) => {
    if (
        editor.dom.readOnly ||
        path.length !== 1 ||
        UNDRAGGABLE.includes(element.type)
    ) {
        return;
    }

    return (props) => <Draggable {...props} />;
};

import { isOrderedList } from '@platejs/list';
import {
    useTodoListElement,
    useTodoListElementState,
} from '@platejs/list/react';
import type { TListElement } from 'platejs';
import type { PlateElementProps, RenderNodeWrapper } from 'platejs/react';
import { useReadOnly } from 'platejs/react';
import type { ReactElement } from 'react';
import {
    isTodoList,
    isWrappedList,
    listClassName,
    listItemClassName,
    listStyle,
    todoMarkerClassName,
} from '@/components/editor/block-list-static';
import { Checkbox } from '@/components/ui/checkbox';
import { cn } from '@/lib/utils';

function TodoMarker(props: PlateElementProps): ReactElement {
    const state = useTodoListElementState({ element: props.element });
    const { checkboxProps } = useTodoListElement(state);
    const readOnly = useReadOnly();

    return (
        <span contentEditable={false}>
            <Checkbox
                aria-label="Задача выполнена"
                className={cn(
                    todoMarkerClassName,
                    readOnly && 'pointer-events-none',
                )}
                {...checkboxProps}
            />
        </span>
    );
}

function List(props: PlateElementProps): ReactElement {
    const element = props.element as TListElement;
    const Tag = isOrderedList(element) ? 'ol' : 'ul';

    return (
        <Tag
            className={listClassName}
            start={element.listStart}
            style={listStyle(element)}
        >
            <li className={listItemClassName(element)}>
                {isTodoList(element) ? <TodoMarker {...props} /> : null}
                {props.children}
            </li>
        </Tag>
    );
}

export const BlockList: RenderNodeWrapper = (props) => {
    if (!isWrappedList(props.element)) {
        return;
    }

    return (wrapped) => <List {...wrapped} />;
};

import {
    ChevronDown,
    Code2,
    Heading2,
    Heading3,
    Heading4,
    Info,
    List,
    ListOrdered,
    ListTodo,
    Minus,
    Pilcrow,
    Plus,
    Quote,
    Table,
} from 'lucide-react';
import { KEYS } from 'platejs';
import type { PlateEditor } from 'platejs/react';
import { useEditorRef, useEditorSelector } from 'platejs/react';
import type { ReactElement, ReactNode } from 'react';
import {
    getCurrentBlockType,
    insertBlock,
    setBlockType,
} from '@/components/editor/editor-transforms';
import { Menu, MenuItem, MenuPopup, MenuTrigger } from '@/components/ui/menu';
import { toggleVariants } from '@/components/ui/toggle';
import { ToolbarButton } from '@/components/ui/toolbar';
import { cn } from '@/lib/utils';

export type BlockOption = {
    value: string;
    label: string;
    icon: ReactNode;
    keywords?: string[];
};

export const TURN_INTO_OPTIONS: BlockOption[] = [
    {
        icon: <Pilcrow />,
        keywords: ['paragraph', 'text', 'текст'],
        label: 'Текст',
        value: KEYS.p,
    },
    {
        icon: <Heading2 />,
        keywords: ['h2', 'heading', 'заголовок'],
        label: 'Заголовок 2',
        value: KEYS.h2,
    },
    {
        icon: <Heading3 />,
        keywords: ['h3', 'heading', 'заголовок'],
        label: 'Заголовок 3',
        value: KEYS.h3,
    },
    {
        icon: <Heading4 />,
        keywords: ['h4', 'heading', 'заголовок'],
        label: 'Заголовок 4',
        value: KEYS.h4,
    },
    {
        icon: <List />,
        keywords: ['ul', 'bullet', 'список'],
        label: 'Маркированный список',
        value: KEYS.ul,
    },
    {
        icon: <ListOrdered />,
        keywords: ['ol', 'numbered', 'список'],
        label: 'Нумерованный список',
        value: KEYS.ol,
    },
    {
        icon: <ListTodo />,
        keywords: ['todo', 'task', 'задача'],
        label: 'Список задач',
        value: KEYS.listTodo,
    },
    {
        icon: <Quote />,
        keywords: ['quote', 'blockquote', 'цитата'],
        label: 'Цитата',
        value: KEYS.blockquote,
    },
    {
        icon: <Code2 />,
        keywords: ['code', 'код'],
        label: 'Блок кода',
        value: KEYS.codeBlock,
    },
];

export const INSERT_OPTIONS: BlockOption[] = [
    {
        icon: <Table />,
        keywords: ['table', 'таблица'],
        label: 'Таблица',
        value: KEYS.table,
    },
    {
        icon: <Info />,
        keywords: ['callout', 'note', 'выноска'],
        label: 'Выноска',
        value: KEYS.callout,
    },
    {
        icon: <Code2 />,
        keywords: ['code', 'код'],
        label: 'Блок кода',
        value: KEYS.codeBlock,
    },
    {
        icon: <Quote />,
        keywords: ['quote', 'цитата'],
        label: 'Цитата',
        value: KEYS.blockquote,
    },
    {
        icon: <Minus />,
        keywords: ['hr', 'divider', 'разделитель'],
        label: 'Разделитель',
        value: KEYS.hr,
    },
];

function MenuButton({
    label,
    children,
}: {
    label: string;
    children: ReactNode;
}): ReactElement {
    return (
        <MenuTrigger
            render={
                <ToolbarButton
                    aria-label={label}
                    onMouseDown={(event) => event.preventDefault()}
                    render={
                        <button
                            className={cn(
                                toggleVariants({ size: 'sm' }),
                                'shrink-0',
                            )}
                            type="button"
                        />
                    }
                />
            }
        >
            {children}
        </MenuTrigger>
    );
}

export function TurnIntoMenu(): ReactElement {
    const editor = useEditorRef();
    const current = useEditorSelector(
        (state) => getCurrentBlockType(state as PlateEditor),
        [],
    );
    const active =
        TURN_INTO_OPTIONS.find((option) => option.value === current) ??
        TURN_INTO_OPTIONS[0];

    return (
        <Menu modal={false}>
            <MenuButton label="Тип блока">
                <span className="min-w-[7.5rem] text-left">{active.label}</span>
                <ChevronDown className="opacity-60" />
            </MenuButton>
            <MenuPopup align="start" finalFocus={false}>
                {TURN_INTO_OPTIONS.map((option) => (
                    <MenuItem
                        key={option.value}
                        onClick={() => {
                            setBlockType(editor, option.value);
                            editor.tf.focus();
                        }}
                    >
                        {option.icon}
                        {option.label}
                    </MenuItem>
                ))}
            </MenuPopup>
        </Menu>
    );
}

export function InsertMenu(): ReactElement {
    const editor = useEditorRef();

    return (
        <Menu modal={false}>
            <MenuButton label="Вставить блок">
                <Plus />
            </MenuButton>
            <MenuPopup align="start" finalFocus={false}>
                {INSERT_OPTIONS.map((option) => (
                    <MenuItem
                        key={option.value}
                        onClick={() => {
                            insertBlock(editor, option.value);
                            editor.tf.focus();
                        }}
                    >
                        {option.icon}
                        {option.label}
                    </MenuItem>
                ))}
            </MenuPopup>
        </Menu>
    );
}

import type { PlateElementProps } from 'platejs/react';
import { PlateElement } from 'platejs/react';
import type { ReactElement } from 'react';
import { blockquoteClassName } from '@/components/editor/blockquote-node-static';

export function BlockquoteElement(props: PlateElementProps): ReactElement {
    return (
        <PlateElement
            {...props}
            as="blockquote"
            className={blockquoteClassName}
        />
    );
}

import { Info } from 'lucide-react';
import type { PlateElementProps } from 'platejs/react';
import { PlateElement } from 'platejs/react';
import type { ReactElement } from 'react';
import { calloutClassName } from '@/components/editor/callout-node-static';

export function CalloutElement({
    children,
    ...props
}: PlateElementProps): ReactElement {
    return (
        <PlateElement {...props} className={calloutClassName}>
            <span className="select-none" contentEditable={false}>
                <Info
                    aria-hidden
                    className="mt-1.5 size-4 shrink-0 text-muted-foreground"
                />
            </span>
            <div className="min-w-0 flex-1">{children}</div>
        </PlateElement>
    );
}

import type { TCodeBlockElement } from 'platejs';
import type { PlateElementProps, PlateLeafProps } from 'platejs/react';
import {
    PlateElement,
    PlateLeaf,
    useEditorRef,
    useReadOnly,
} from 'platejs/react';
import type { ReactElement } from 'react';
import {
    codeBlockClassName,
    syntaxClassName,
} from '@/components/editor/code-block-node-static';
import { cn } from '@/lib/utils';

export const CODE_LANGUAGES = [
    { label: 'Текст', value: 'plaintext' },
    { label: 'Bash', value: 'bash' },
    { label: 'CSS', value: 'css' },
    { label: 'HTML', value: 'xml' },
    { label: 'JavaScript', value: 'javascript' },
    { label: 'JSON', value: 'json' },
    { label: 'PHP', value: 'php' },
    { label: 'Python', value: 'python' },
    { label: 'SQL', value: 'sql' },
    { label: 'TypeScript', value: 'typescript' },
];

function CodeLanguageSelect({
    element,
}: {
    element: TCodeBlockElement;
}): ReactElement {
    const editor = useEditorRef();

    return (
        <select
            aria-label="Язык кода"
            className="absolute top-2 right-2 z-10 h-7 rounded-md border border-input bg-background px-2 font-sans text-muted-foreground text-xs outline-none focus-visible:ring-2 focus-visible:ring-ring"
            contentEditable={false}
            onChange={(event) =>
                editor.tf.setNodes<TCodeBlockElement>(
                    { lang: event.target.value },
                    { at: element },
                )
            }
            value={element.lang ?? 'plaintext'}
        >
            {CODE_LANGUAGES.map((language) => (
                <option key={language.value} value={language.value}>
                    {language.label}
                </option>
            ))}
        </select>
    );
}

export function CodeBlockElement({
    children,
    ...props
}: PlateElementProps<TCodeBlockElement>): ReactElement {
    const readOnly = useReadOnly();

    return (
        <PlateElement {...props} className={cn('relative', codeBlockClassName)}>
            {readOnly ? null : <CodeLanguageSelect element={props.element} />}
            <pre className="m-0">
                <code>{children}</code>
            </pre>
        </PlateElement>
    );
}

export function CodeLineElement(props: PlateElementProps): ReactElement {
    return <PlateElement {...props} />;
}

export function CodeSyntaxLeaf(props: PlateLeafProps): ReactElement {
    return (
        <PlateLeaf
            {...props}
            className={syntaxClassName(props.leaf.className)}
        />
    );
}

import type { PlateLeafProps } from 'platejs/react';
import { PlateLeaf } from 'platejs/react';
import type { ReactElement } from 'react';
import { codeLeafClassName } from '@/components/editor/code-node-static';

export function CodeLeaf(props: PlateLeafProps): ReactElement {
    return <PlateLeaf {...props} as="code" className={codeLeafClassName} />;
}

import type { ReactElement } from 'react';
import type { EditorProps } from '@/components/editor/editor';
import { Editor } from '@/components/editor/editor';
import { FormField } from '@/components/form/form-field';
import type { FormFieldBaseProps } from '@/components/form/types';

export type EditorFieldProps = FormFieldBaseProps &
    Pick<
        EditorProps,
        | 'placeholder'
        | 'uploadImage'
        | 'onUploadError'
        | 'contentClassName'
        | 'children'
    > & {
        editorClassName?: string;
    };

export function EditorField({
    placeholder,
    uploadImage,
    onUploadError,
    contentClassName,
    editorClassName,
    children,
    ...props
}: EditorFieldProps): ReactElement {
    return (
        <FormField {...props}>
            {({ field, ...aria }) => (
                <Editor
                    {...aria}
                    aria-label={
                        aria['aria-label'] ??
                        (typeof props.label === 'string'
                            ? props.label
                            : undefined)
                    }
                    className={editorClassName}
                    contentClassName={contentClassName}
                    disabled={field.disabled}
                    name={field.name}
                    onBlur={field.onBlur}
                    onChange={field.onChange}
                    placeholder={placeholder}
                    onUploadError={onUploadError}
                    uploadImage={uploadImage}
                    value={field.value}
                >
                    {children}
                </Editor>
            )}
        </FormField>
    );
}

import {
    BlockquoteRules,
    BoldRules,
    CodeRules,
    HeadingRules,
    HorizontalRuleRules,
    ItalicRules,
    MarkComboRules,
    StrikethroughRules,
    UnderlineRules,
} from '@platejs/basic-nodes';
import {
    BlockquotePlugin,
    BoldPlugin,
    CodePlugin,
    H2Plugin,
    H3Plugin,
    H4Plugin,
    HorizontalRulePlugin,
    ItalicPlugin,
    StrikethroughPlugin,
    UnderlinePlugin,
} from '@platejs/basic-nodes/react';
import { CalloutPlugin } from '@platejs/callout/react';
import { CodeBlockRules } from '@platejs/code-block';
import {
    CodeBlockPlugin,
    CodeLinePlugin,
    CodeSyntaxPlugin,
} from '@platejs/code-block/react';
import { DndPlugin } from '@platejs/dnd';
import { IndentPlugin } from '@platejs/indent/react';
import { LinkRules } from '@platejs/link';
import { LinkPlugin } from '@platejs/link/react';
import {
    BulletedListRules,
    OrderedListRules,
    TaskListRules,
} from '@platejs/list';
import { ListPlugin } from '@platejs/list/react';
import { MarkdownPlugin } from '@platejs/markdown';
import { ImagePlugin } from '@platejs/media/react';
import { SlashInputPlugin, SlashPlugin } from '@platejs/slash-command/react';
import {
    TableCellHeaderPlugin,
    TableCellPlugin,
    TablePlugin,
    TableRowPlugin,
} from '@platejs/table/react';
import type { SlateEditor } from 'platejs';
import { ExitBreakPlugin, KEYS, TrailingBlockPlugin } from 'platejs';
import { createPlatePlugin, ParagraphPlugin } from 'platejs/react';
import { DndProvider } from 'react-dnd';
import { HTML5Backend } from 'react-dnd-html5-backend';
import remarkGfm from 'remark-gfm';
import { INDENT_TARGETS, lowlight } from '@/components/editor/base-editor-kit';
import { BlockDraggable } from '@/components/editor/block-draggable';
import { BlockList } from '@/components/editor/block-list';
import {
    isBulletList,
    LIST_INDENT,
} from '@/components/editor/block-list-static';
import { BlockquoteElement } from '@/components/editor/blockquote-node';
import { CalloutElement } from '@/components/editor/callout-node';
import {
    CodeBlockElement,
    CodeLineElement,
    CodeSyntaxLeaf,
} from '@/components/editor/code-block-node';
import { CodeLeaf } from '@/components/editor/code-node';
import {
    EditorUploadPlugin,
    EditorUrlPolicyPlugin,
    imageFiles,
    insertUploadedImages,
} from '@/components/editor/editor-upload';
import {
    isAllowedImageUrl,
    isAllowedLinkUrl,
    LINK_SCHEMES,
} from '@/components/editor/editor-url';
import { FloatingToolbar } from '@/components/editor/floating-toolbar';
import {
    H2Element,
    H3Element,
    H4Element,
} from '@/components/editor/heading-node';
import { HrElement } from '@/components/editor/hr-node';
import { ImageElement } from '@/components/editor/image-node';
import { LinkElement } from '@/components/editor/link-node';
import { LinkFloatingToolbar } from '@/components/editor/link-toolbar';
import { ParagraphElement } from '@/components/editor/paragraph-node';
import { SlashInputElement } from '@/components/editor/slash-node';
import {
    TableCellElement,
    TableCellHeaderElement,
    TableElement,
    TableRowElement,
} from '@/components/editor/table-node';

const headingConfig = {
    inputRules: [HeadingRules.markdown()],
    rules: { break: { empty: 'reset' as const } },
};

export const EditorKit = [
    ParagraphPlugin.withComponent(ParagraphElement),
    H2Plugin.configure({
        ...headingConfig,
        node: { component: H2Element },
        shortcuts: { toggle: { keys: 'mod+alt+2' } },
    }),
    H3Plugin.configure({
        ...headingConfig,
        node: { component: H3Element },
        shortcuts: { toggle: { keys: 'mod+alt+3' } },
    }),
    H4Plugin.configure({
        ...headingConfig,
        node: { component: H4Element },
        shortcuts: { toggle: { keys: 'mod+alt+4' } },
    }),
    BlockquotePlugin.configure({
        inputRules: [BlockquoteRules.markdown()],
        node: { component: BlockquoteElement },
    }),
    HorizontalRulePlugin.configure({
        inputRules: [HorizontalRuleRules.markdown({ variant: '-' })],
        node: { component: HrElement },
    }),
    BoldPlugin.configure({
        inputRules: [
            BoldRules.markdown({ variant: '*' }),
            BoldRules.markdown({ variant: '_' }),
            MarkComboRules.markdown({ variant: 'boldItalic' }),
        ],
    }),
    ItalicPlugin.configure({
        inputRules: [
            ItalicRules.markdown({ variant: '*' }),
            ItalicRules.markdown({ variant: '_' }),
        ],
    }),
    UnderlinePlugin.configure({ inputRules: [UnderlineRules.markdown()] }),
    StrikethroughPlugin.configure({
        inputRules: [StrikethroughRules.markdown()],
    }),
    CodePlugin.configure({
        inputRules: [CodeRules.markdown()],
        node: { component: CodeLeaf },
    }),
    LinkPlugin.configure({
        inputRules: [
            LinkRules.markdown(),
            LinkRules.autolink({ variant: 'paste' }),
            LinkRules.autolink({ variant: 'space' }),
        ],
        node: { props: () => ({}) },
        options: { allowedSchemes: LINK_SCHEMES, isUrl: isAllowedLinkUrl },
        render: {
            afterEditable: () => <LinkFloatingToolbar />,
            node: LinkElement,
        },
    }),
    IndentPlugin.configure({
        inject: { targetPlugins: INDENT_TARGETS },
        options: { offset: LIST_INDENT },
    }),
    ListPlugin.configure({
        inject: {
            nodeProps: {
                nodeKey: KEYS.listType,
                query: ({ nodeProps }) =>
                    nodeProps.element !== undefined &&
                    isBulletList(nodeProps.element),
                transformProps: ({ props }) => ({
                    ...props,
                    style: { ...props.style, display: 'list-item' },
                }),
            },
            targetPlugins: INDENT_TARGETS,
        },
        inputRules: [
            BulletedListRules.markdown({ variant: '-' }),
            BulletedListRules.markdown({ variant: '*' }),
            OrderedListRules.markdown({ variant: '.' }),
            TaskListRules.markdown({ checked: false }),
            TaskListRules.markdown({ checked: true }),
        ],
        render: { belowNodes: BlockList },
    }),
    CalloutPlugin.withComponent(CalloutElement),
    CodeBlockPlugin.configure({
        inputRules: [CodeBlockRules.markdown({ on: 'match' })],
        node: { component: CodeBlockElement },
        options: { lowlight },
    }),
    CodeLinePlugin.withComponent(CodeLineElement),
    CodeSyntaxPlugin.withComponent(CodeSyntaxLeaf),
    ImagePlugin.configure({
        node: { component: ImageElement },
        options: { disableUploadInsert: true, isUrl: isAllowedImageUrl },
    }),
    TablePlugin.withComponent(TableElement),
    TableRowPlugin.withComponent(TableRowElement),
    TableCellPlugin.withComponent(TableCellElement),
    TableCellHeaderPlugin.withComponent(TableCellHeaderElement),
    SlashPlugin.configure({
        options: {
            triggerQuery: (editor: SlateEditor) =>
                !editor.api.some({
                    match: { type: editor.getType(KEYS.codeBlock) },
                }),
        },
    }),
    SlashInputPlugin.withComponent(SlashInputElement),
    DndPlugin.configure({
        options: {
            enableScroller: true,
            onDropFiles: ({ dragItem, editor, target }) => {
                const uploadImage = editor.getOption(
                    EditorUploadPlugin,
                    'uploadImage',
                );
                const files = imageFiles(dragItem.files);

                if (uploadImage && files.length > 0) {
                    void insertUploadedImages(
                        editor,
                        files,
                        uploadImage,
                        target,
                    );
                }
            },
        },
        render: {
            aboveNodes: BlockDraggable,
            aboveSlate: ({ children }) => (
                <DndProvider backend={HTML5Backend}>{children}</DndProvider>
            ),
        },
    }),
    MarkdownPlugin.configure({ options: { remarkPlugins: [remarkGfm] } }),
    ExitBreakPlugin.configure({
        shortcuts: {
            insert: { keys: 'mod+enter' },
            insertBefore: { keys: 'mod+shift+enter' },
        },
    }),
    TrailingBlockPlugin.configure({ options: { type: KEYS.p } }),
    EditorUploadPlugin,
    EditorUrlPolicyPlugin,
    createPlatePlugin({
        key: 'floatingToolbar',
        render: { afterEditable: () => <FloatingToolbar /> },
    }),
];

import type { ReactElement, ReactNode } from 'react';
import { Toggle, toggleVariants } from '@/components/ui/toggle';
import type { ToolbarPrimitive } from '@/components/ui/toolbar';
import {
    ToolbarButton,
    ToolbarGroup,
    ToolbarSeparator,
} from '@/components/ui/toolbar';
import { Tooltip, TooltipPopup, TooltipTrigger } from '@/components/ui/tooltip';
import { cn } from '@/lib/utils';

export type EditorToolbarButtonProps = Omit<
    ToolbarPrimitive.Button.Props,
    'children'
> & {
    label: string;
    pressed?: boolean;
    children: ReactNode;
};

export function EditorToolbarButton({
    label,
    pressed,
    className,
    children,
    onMouseDown,
    ...props
}: EditorToolbarButtonProps): ReactElement {
    return (
        <Tooltip>
            <TooltipTrigger
                render={
                    <ToolbarButton
                        aria-label={label}
                        onMouseDown={(event) => {
                            event.preventDefault();
                            onMouseDown?.(event);
                        }}
                        render={
                            pressed === undefined ? (
                                <button
                                    className={cn(
                                        toggleVariants({ size: 'sm' }),
                                        'shrink-0',
                                        className,
                                    )}
                                    type="button"
                                />
                            ) : (
                                <Toggle
                                    className={cn('shrink-0', className)}
                                    pressed={pressed}
                                    size="sm"
                                />
                            )
                        }
                        {...props}
                    />
                }
            >
                {children}
            </TooltipTrigger>
            <TooltipPopup>{label}</TooltipPopup>
        </Tooltip>
    );
}

export function EditorToolbarGroup({
    className,
    ...props
}: ToolbarPrimitive.Group.Props): ReactElement {
    return <ToolbarGroup className={cn('gap-0.5', className)} {...props} />;
}

export function EditorToolbarSeparator(): ReactElement {
    return <ToolbarSeparator className="mx-1" orientation="vertical" />;
}

import { insertCallout } from '@platejs/callout';
import { toggleCodeBlock, unwrapCodeBlock } from '@platejs/code-block';
import { TablePlugin } from '@platejs/table/react';
import type { NodeEntry, Path, TElement } from 'platejs';
import { KEYS, PathApi } from 'platejs';
import type { PlateEditor } from 'platejs/react';

export const LIST_TYPES = [KEYS.ul, KEYS.ol, KEYS.listTodo] as string[];

const TURN_INTO_TYPES: string[] = [
    KEYS.p,
    KEYS.h2,
    KEYS.h3,
    KEYS.h4,
    KEYS.blockquote,
    KEYS.codeBlock,
    ...LIST_TYPES,
];

const CONTAINER_TYPES: string[] = [KEYS.codeBlock, KEYS.table, KEYS.blockquote];

const insertBlockMap: Record<string, (editor: PlateEditor, at: Path) => void> =
    {
        [KEYS.callout]: (editor, at) =>
            insertCallout(editor, { at, select: true }),
        [KEYS.codeBlock]: (editor, at) =>
            editor.tf.insertNodes(
                {
                    children: [
                        { children: [{ text: '' }], type: KEYS.codeLine },
                    ],
                    type: KEYS.codeBlock,
                },
                { at, select: true },
            ),
        [KEYS.table]: (editor, at) =>
            editor
                .getTransforms(TablePlugin)
                .insert.table(
                    { colCount: 3, header: true, rowCount: 3 },
                    { at, select: true },
                ),
    };

export function getBlockType(block: TElement | undefined): string {
    if (!block) {
        return KEYS.p;
    }

    const listStyleType = block[KEYS.listType] as string | undefined;

    if (listStyleType) {
        return listStyleType === KEYS.ol || listStyleType === KEYS.listTodo
            ? listStyleType
            : KEYS.ul;
    }

    return block.type;
}

function isInside(editor: PlateEditor, type: string): boolean {
    return editor.api.some({ match: { type: editor.getType(type) } });
}

export function getCurrentBlockType(editor: PlateEditor): string {
    if (isInside(editor, KEYS.codeBlock)) {
        return KEYS.codeBlock;
    }

    if (isInside(editor, KEYS.blockquote)) {
        return KEYS.blockquote;
    }

    return getBlockType(editor.api.block()?.[0]);
}

export function insertBlock(editor: PlateEditor, type: string): void {
    const top = editor.api.block({ highest: true });

    if (!top) {
        return;
    }

    const [node, path] = top;
    const isContainer = CONTAINER_TYPES.includes(node.type);
    const isEmpty = !isContainer && editor.api.isEmpty(node);
    const lowest = editor.api.block();
    const isEmptyInQuote =
        node.type === KEYS.blockquote &&
        lowest !== undefined &&
        editor.api.isEmpty(lowest[0]);

    if ((isEmpty || isEmptyInQuote) && TURN_INTO_TYPES.includes(type)) {
        setBlockType(editor, type);

        return;
    }

    editor.tf.withoutNormalizing(() => {
        const at = PathApi.next(path);

        if (type in insertBlockMap) {
            insertBlockMap[type](editor, at);
        } else if (LIST_TYPES.includes(type)) {
            editor.tf.insertNodes(
                editor.api.create.block({ indent: 1, listStyleType: type }),
                { at, select: true },
            );
        } else {
            editor.tf.insertNodes(editor.api.create.block({ type }), {
                at,
                select: true,
            });
        }

        if (isEmpty) {
            editor.tf.removeNodes({ at: path });
        }
    });
}

function unsetList(editor: PlateEditor): void {
    for (const [node, path] of editor.api.blocks<TElement>({
        mode: 'lowest',
    })) {
        if (node[KEYS.listType]) {
            editor.tf.unsetNodes([KEYS.listType, 'indent', 'checked'], {
                at: path,
            });
        }
    }
}

function setBlock(
    editor: PlateEditor,
    type: string,
    [node, path]: NodeEntry<TElement>,
): void {
    if (node[KEYS.listType]) {
        editor.tf.unsetNodes([KEYS.listType, 'indent', 'checked'], {
            at: path,
        });
    }

    if (LIST_TYPES.includes(type)) {
        if (node.type !== KEYS.p) {
            editor.tf.setNodes({ type: KEYS.p }, { at: path });
        }

        editor.tf.setNodes(
            editor.api.create.block({ indent: 1, listStyleType: type }),
            { at: path },
        );

        return;
    }

    if (node.type !== type) {
        editor.tf.setNodes({ type }, { at: path });
    }
}

export function setBlockType(editor: PlateEditor, type: string): void {
    const current = getCurrentBlockType(editor);

    if (current === type) {
        return;
    }

    editor.tf.withoutNormalizing(() => {
        if (current === KEYS.codeBlock) {
            unwrapCodeBlock(editor);
        }

        if (current === KEYS.blockquote) {
            editor.tf.toggleBlock(KEYS.blockquote, { wrap: true });
        }

        if (type === KEYS.codeBlock) {
            unsetList(editor);
            toggleCodeBlock(editor);

            return;
        }

        if (type === KEYS.blockquote) {
            unsetList(editor);
            editor.tf.toggleBlock(KEYS.blockquote, { wrap: true });

            return;
        }

        for (const entry of editor.api.blocks<TElement>({ mode: 'lowest' })) {
            setBlock(editor, type, entry);
        }
    });
}

import { insertImage } from '@platejs/media';
import type { Path, PathRef, SlateEditor, TElement } from 'platejs';
import { KEYS, PathApi } from 'platejs';
import { createPlatePlugin } from 'platejs/react';
import {
    isAllowedImageUrl,
    isAllowedLinkUrl,
} from '@/components/editor/editor-url';

export type UploadImage = (file: File) => Promise<string>;

export type UploadError = (error: unknown) => void;

export class RejectedUploadUrlError extends Error {
    constructor(public url: string) {
        super(`uploadImage returned a url the editor cannot show: ${url}`);
    }
}

export const EditorUploadPlugin = createPlatePlugin({
    key: 'editorUpload',
    options: {
        onUploadError: null as UploadError | null,
        uploadImage: null as UploadImage | null,
    },
}).overrideEditor(({ editor, getOption, tf: { insertData } }) => ({
    transforms: {
        insertData(data) {
            const uploadImage = getOption('uploadImage');
            const images = imageFiles(data.files);

            if (!uploadImage || images.length === 0) {
                insertData(data);

                return;
            }

            insertUploadedImages(editor, images, uploadImage).catch(
                (error: unknown) => getOption('onUploadError')?.(error),
            );
        },
    },
}));

export const EditorUrlPolicyPlugin = createPlatePlugin({
    key: 'editorUrlPolicy',
}).overrideEditor(({ editor, tf: { normalizeNode } }) => ({
    transforms: {
        normalizeNode(entry) {
            const [node, path] = entry as [TElement, Path];

            if (node.type === KEYS.link && !isAllowedLinkUrl(node.url)) {
                editor.tf.unwrapNodes({ at: path });

                return;
            }

            if (node.type === KEYS.img && !isAllowedImageUrl(node.url)) {
                editor.tf.removeNodes({ at: path });

                return;
            }

            normalizeNode(entry);
        },
    },
}));

export function imageFiles(
    files: FileList | File[] | null | undefined,
): File[] {
    return [...(files ?? [])].filter((file) => file.type.startsWith('image/'));
}

function absoluteUrl(url: string): string {
    try {
        return new URL(url, window.location.href).href;
    } catch {
        return url;
    }
}

export async function insertUploadedImages(
    editor: SlateEditor,
    files: File[],
    uploadImage: UploadImage,
    at?: Path,
): Promise<void> {
    let target: PathRef | null = at ? editor.api.pathRef(at) : null;

    try {
        for (const file of files) {
            const url = absoluteUrl(await uploadImage(file));

            if (!isAllowedImageUrl(url)) {
                throw new RejectedUploadUrlError(url);
            }

            const path = target?.current ?? undefined;

            insertImage(
                editor,
                url,
                path ? { at: path, nextBlock: false } : undefined,
            );

            if (target && path) {
                target.unref();
                target = editor.api.pathRef(PathApi.next(path));
            }
        }
    } finally {
        target?.unref();
    }
}

import type { PlateContentProps } from 'platejs/react';
import {
    Plate,
    PlateContainer,
    PlateContent,
    usePlateEditor,
} from 'platejs/react';
import type { ReactElement, ReactNode } from 'react';
import { useEffect } from 'react';
import { EditorKit } from '@/components/editor/editor-kit';
import { editorContentClassName } from '@/components/editor/editor-static';
import type {
    UploadError,
    UploadImage,
} from '@/components/editor/editor-upload';
import { EditorUploadPlugin } from '@/components/editor/editor-upload';
import type { EditorValue } from '@/components/editor/editor-value';
import { EMPTY_EDITOR_VALUE } from '@/components/editor/editor-value';
import { FixedToolbar } from '@/components/editor/fixed-toolbar';
import { cn } from '@/lib/utils';

export type EditorProps = Pick<
    PlateContentProps,
    | 'id'
    | 'aria-label'
    | 'aria-labelledby'
    | 'aria-describedby'
    | 'aria-invalid'
    | 'onBlur'
    | 'placeholder'
    | 'name'
> & {
    value?: EditorValue | null;
    onChange?: (value: EditorValue) => void;
    uploadImage?: UploadImage;
    onUploadError?: UploadError;
    disabled?: boolean;
    className?: string;
    contentClassName?: string;
    children?: ReactNode;
};

export function Editor({
    value,
    onChange,
    uploadImage,
    onUploadError,
    disabled = false,
    placeholder = 'Начните писать или нажмите / для вставки блока',
    className,
    contentClassName,
    children,
    ...contentProps
}: EditorProps): ReactElement {
    const editor = usePlateEditor({
        plugins: EditorKit,
        value: value && value.length > 0 ? value : EMPTY_EDITOR_VALUE,
    });

    useEffect(() => {
        editor.setOption(
            EditorUploadPlugin,
            'uploadImage',
            uploadImage ?? null,
        );
        editor.setOption(
            EditorUploadPlugin,
            'onUploadError',
            onUploadError ?? null,
        );
    }, [editor, onUploadError, uploadImage]);

    useEffect(() => {
        if (!value || value === editor.children) {
            return;
        }

        const next = value.length > 0 ? value : EMPTY_EDITOR_VALUE;

        if (JSON.stringify(next) === JSON.stringify(editor.children)) {
            return;
        }

        editor.tf.setValue(next);
    }, [editor, value]);

    return (
        <Plate
            editor={editor}
            onValueChange={({ value: next }) => onChange?.(next)}
            readOnly={disabled}
        >
            <div
                className={cn(
                    'relative w-full rounded-lg border border-input bg-background not-dark:bg-clip-padding shadow-xs/5 transition-shadow has-[[data-slate-editor]:focus-visible]:border-ring has-aria-invalid:border-destructive/36 has-[[data-slate-editor]:focus-visible]:ring-[3px] has-[[data-slate-editor]:focus-visible]:ring-ring/24 dark:bg-input/32',
                    disabled && 'opacity-64',
                    className,
                )}
                data-slot="editor"
            >
                {disabled ? null : <FixedToolbar />}
                <PlateContainer className="relative">
                    <PlateContent
                        {...contentProps}
                        className={cn(
                            editorContentClassName,
                            'min-h-80 px-5 pt-4 pb-16 outline-none sm:px-12 [&_[data-slate-placeholder]]:text-muted-foreground/72 [&_[data-slate-placeholder]]:opacity-100!',
                            contentClassName,
                        )}
                        disableDefaultStyles
                        placeholder={placeholder}
                    />
                </PlateContainer>
            </div>
            {children}
        </Plate>
    );
}

