    useEditorSelection,
    useFormInputProps,
} from 'platejs/react';
import type { ReactElement } from 'react';
import { useMemo } from 'react';
import { EditorToolbarButton } from '@/components/editor/editor-toolbar';
import { buttonVariants } from '@/components/ui/button';
import { Separator } from '@/components/ui/separator';

const floatingOptions: UseVirtualFloatingOptions = {
    middleware: [
        offset(8),
        flip({
            fallbackPlacements: ['bottom-end', 'top-start', 'top-end'],
            padding: 12,
        }),
    ],
    placement: 'bottom-start',
};

const popoverClassName =
    'z-50 w-auto rounded-lg border bg-popover p-1 text-popover-foreground shadow-lg/5 outline-hidden';

const inputClassName =
    'flex h-8 w-full rounded-md border-none bg-transparent px-1.5 text-base outline-none placeholder:text-muted-foreground sm:text-sm';

export function LinkToolbarButton(): ReactElement {
    const state = useLinkToolbarButtonState();
    const { props } = useLinkToolbarButton(state);

    return (
        <EditorToolbarButton
            data-plate-focus
            label="Ссылка"
            onClick={props.onClick}
            pressed={props.pressed}
        >
            <Link />
        </EditorToolbarButton>
    );
}

function LinkOpenButton(): ReactElement | null {
    const editor = useEditorRef();
    const selection = useEditorSelection();

    const href = useMemo(() => {
        if (!selection) {
            return undefined;
        }

        const entry = editor.api.node<TLinkElement>({
            match: { type: editor.getType(KEYS.link) },
        });

        return entry ? getLinkAttributes(editor, entry[0]).href : undefined;
    }, [editor, selection]);

    if (!href) {
        return null;
    }

    return (
        <a
            aria-label="Открыть ссылку"
            className={buttonVariants({ size: 'icon-sm', variant: 'ghost' })}
            href={href}
            rel="noopener noreferrer"
            target="_blank"
        >
            <ExternalLink />
        </a>
    );
}

export function LinkFloatingToolbar(): ReactElement | null {
    const insertState = useFloatingLinkInsertState({ floatingOptions });
    const {
        hidden,
        props: insertProps,
        ref: insertRef,
        textInputProps,
    } = useFloatingLinkInsert(insertState);

    const editState = useFloatingLinkEditState({ floatingOptions });
    const {
        editButtonProps,
        props: editProps,
        ref: editRef,
        unlinkButtonProps,
    } = useFloatingLinkEdit(editState);

    const inputProps = useFormInputProps({
        preventDefaultOnEnterKeydown: true,
    });

    if (hidden) {
        return null;
    }

    const input = (
        <div className="flex w-[330px] flex-col" {...inputProps}>
            <div className="flex items-center">
                <Link className="mx-2 size-4 shrink-0 text-muted-foreground" />
                <FloatingLinkUrlInput
                    aria-label="Адрес ссылки"
                    className={inputClassName}
                    data-plate-focus
                    placeholder="https://"
                />
            </div>
            <Separator className="my-1" />
            <div className="flex items-center">
                <Text className="mx-2 size-4 shrink-0 text-muted-foreground" />
                <input
                    aria-label="Текст ссылки"
                    className={inputClassName}
                    data-plate-focus
                    placeholder="Текст ссылки"
                    {...textInputProps}
                />
            </div>
        </div>
    );

    const editContent = editState.isEditing ? (
        input
    ) : (
        <div className="flex items-center gap-0.5">
            <button
                className={buttonVariants({ size: 'sm', variant: 'ghost' })}
                type="button"
                {...editButtonProps}
            >
                Изменить
            </button>
            <Separator className="h-5" orientation="vertical" />
            <LinkOpenButton />
            <button
                aria-label="Убрать ссылку"
                className={buttonVariants({
                    size: 'icon-sm',
                    variant: 'ghost',
                })}
                type="button"
                {...unlinkButtonProps}
            >
                <Unlink />
            </button>
        </div>
    );

    return (
        <>
            <div className={popoverClassName} ref={insertRef} {...insertProps}>
                {input}
            </div>
            <div className={popoverClassName} ref={editRef} {...editProps}>
                {editContent}
            </div>
        </>
    );
}

import type { PlateElementProps } from 'platejs/react';
import { PlateElement } from 'platejs/react';
import type { ReactElement } from 'react';
import { paragraphClassName } from '@/components/editor/paragraph-node-static';

export function ParagraphElement(props: PlateElementProps): ReactElement {
    return <PlateElement {...props} className={paragraphClassName} />;
}

import { filterWords } from '@platejs/combobox';
import {
    useComboboxInput,
    useHTMLInputCursorState,
} from '@platejs/combobox/react';
import type { PointRef, TComboboxInputElement } from 'platejs';
import type { PlateElementProps } from 'platejs/react';
import { PlateElement, useEditorRef } from 'platejs/react';
import type { KeyboardEvent, ReactElement } from 'react';
import { useEffect, useId, useMemo, useRef, useState } from 'react';
import type { BlockOption } from '@/components/editor/block-menus';
import {
    INSERT_OPTIONS,
    TURN_INTO_OPTIONS,
} from '@/components/editor/block-menus';
import { insertBlock } from '@/components/editor/editor-transforms';
import { cn } from '@/lib/utils';

const SLASH_OPTIONS: BlockOption[] = [
    ...TURN_INTO_OPTIONS,
    ...INSERT_OPTIONS.filter(
        (option) =>
            !TURN_INTO_OPTIONS.some((block) => block.value === option.value),
    ),
];

function matches(option: BlockOption, search: string): boolean {
    if (!search) {
        return true;
    }

    return [option.label, option.value, ...(option.keywords ?? [])].some(
        (term) => filterWords(term, search),
    );
}

function SlashCombobox({
    element,
}: {
    element: TComboboxInputElement;
}): ReactElement {
    const editor = useEditorRef();
    const inputRef = useRef<HTMLInputElement>(null);
    const cursorState = useHTMLInputCursorState(inputRef);
    const insertPoint = useRef<PointRef | null>(null);
    const [search, setSearch] = useState('');
    const [active, setActive] = useState(0);
    const listId = useId();

    useEffect(() => {
        const path = editor.api.findPath(element);
        const point = path ? editor.api.before(path) : undefined;

        if (!point) {
            return;
        }

        const pointRef = editor.api.pointRef(point);

        insertPoint.current = pointRef;

        return () => {
            pointRef.unref();
        };
    }, [editor, element]);

    const { props: inputProps, removeInput } = useComboboxInput({
        autoFocus: true,
        cancelInputOnBlur: true,
        cursorState,
        onCancelInput: (cause) => {
            if (cause !== 'backspace') {
                editor.tf.insertText(`/${search}`, {
                    at: insertPoint.current?.current ?? undefined,
                });
            }
        },
        ref: inputRef,
    });

    const options = useMemo(
        () => SLASH_OPTIONS.filter((option) => matches(option, search)),
        [search],
    );

    useEffect(() => {
        document
            .getElementById(`${listId}-${active}`)
            ?.scrollIntoView({ block: 'nearest' });
    }, [active, listId]);

    const choose = (option: BlockOption | undefined): void => {
        if (!option) {
            return;
        }

        removeInput(true);
        insertBlock(editor, option.value);
    };

    const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>): void => {
        if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
            event.preventDefault();

            const step = event.key === 'ArrowDown' ? 1 : -1;

            setActive((current) =>
                options.length === 0
                    ? 0
                    : (current + step + options.length) % options.length,
            );

            return;
        }

        if (event.key === 'Enter') {
            event.preventDefault();
            choose(options[active]);

            return;
        }

        inputProps.onKeyDown(event);
    };

    return (
        <span className="relative" contentEditable={false}>
            /
            <input
                aria-activedescendant={
                    options[active] ? `${listId}-${active}` : undefined
                }
                aria-autocomplete="list"
                aria-controls={listId}
                aria-expanded
                aria-label="Поиск блока"
                className="w-24 bg-transparent outline-none"
                onBlur={inputProps.onBlur}
                onChange={(event) => {
                    setSearch(event.target.value);
                    setActive(0);
                }}
                onKeyDown={handleKeyDown}
                ref={inputRef}
                role="combobox"
                value={search}
            />
            <span
                className="absolute top-full left-0 z-50 mt-1 flex max-h-72 w-64 flex-col overflow-y-auto rounded-lg border bg-popover p-1 font-normal text-base text-popover-foreground shadow-lg/5 sm:text-sm"
                id={listId}
                role="listbox"
            >
                {options.length === 0 ? (
                    <span className="px-2 py-1.5 text-muted-foreground">
                        Ничего не найдено
                    </span>
                ) : (
                    options.map((option, index) => (
                        <span
                            aria-selected={index === active}
                            className={cn(
                                'flex min-h-8 cursor-pointer select-none items-center gap-2 rounded-sm px-2 py-1 sm:min-h-7 [&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:opacity-80',
                                index === active &&
                                    'bg-accent text-accent-foreground',
                            )}
                            id={`${listId}-${index}`}
                            key={option.value}
                            onMouseDown={(event) => {
                                event.preventDefault();
                                choose(option);
                            }}
                            onMouseEnter={() => setActive(index)}
                            role="option"
                            tabIndex={-1}
                        >
                            {option.icon}
                            {option.label}
                        </span>
                    ))
                )}
            </span>
        </span>
    );
}

export function SlashInputElement(
    props: PlateElementProps<TComboboxInputElement>,
): ReactElement {
    return (
        <PlateElement {...props} as="span">
            <SlashCombobox element={props.element} />
            {props.children}
        </PlateElement>
    );
}

import { TablePlugin } from '@platejs/table/react';
import {
    ArrowDownToLine,
    ArrowLeftToLine,
    ArrowRightToLine,
    ArrowUpToLine,
    Columns2,
    Rows2,
    Trash2,
} from 'lucide-react';
import type { TTableCellElement, TTableElement } from 'platejs';
import type { PlateElementProps } from 'platejs/react';
import {
    PlateElement,
    useEditorPlugin,
    useFocused,
    useReadOnly,
    useSelected,
} from 'platejs/react';
import type { ReactElement, ReactNode } from 'react';
import {
    tableCellClassName,
    tableClassName,
} from '@/components/editor/table-node-static';
import { Button } from '@/components/ui/button';
import { Separator } from '@/components/ui/separator';
import { cn } from '@/lib/utils';

function TableAction({
    label,
    onClick,
    children,
}: {
    label: string;
    onClick: () => void;
    children: ReactNode;
}): ReactElement {
    return (
        <Button
            aria-label={label}
            onClick={onClick}
            onMouseDown={(event) => event.preventDefault()}
            size="icon-sm"
            title={label}
            variant="ghost"
        >
            {children}
        </Button>
    );
}

function TableToolbar(): ReactElement {
    const { tf } = useEditorPlugin(TablePlugin);

    return (
        <div
            className="absolute -top-11 right-0 z-20 flex items-center gap-0.5 rounded-lg border bg-popover p-1 shadow-lg/5"
            contentEditable={false}
            role="toolbar"
            aria-label="Таблица"
        >
            <TableAction
                label="Строка выше"
                onClick={() => tf.insert.tableRow({ before: true })}
            >
                <ArrowUpToLine />
            </TableAction>
            <TableAction
                label="Строка ниже"
                onClick={() => tf.insert.tableRow()}
            >
                <ArrowDownToLine />
            </TableAction>
            <TableAction
                label="Столбец слева"
                onClick={() => tf.insert.tableColumn({ before: true })}
            >
                <ArrowLeftToLine />
            </TableAction>
            <TableAction
                label="Столбец справа"
                onClick={() => tf.insert.tableColumn()}
            >
                <ArrowRightToLine />
            </TableAction>
            <Separator className="mx-0.5 h-5" orientation="vertical" />
            <TableAction
                label="Удалить строку"
                onClick={() => tf.remove.tableRow()}
            >
                <Rows2 />
            </TableAction>
            <TableAction
                label="Удалить столбец"
                onClick={() => tf.remove.tableColumn()}
            >
                <Columns2 />
            </TableAction>
            <TableAction
                label="Удалить таблицу"
                onClick={() => tf.remove.table()}
            >
                <Trash2 />
            </TableAction>
        </div>
    );
}

export function TableElement({
    children,
    ...props
}: PlateElementProps<TTableElement>): ReactElement {
    const selected = useSelected();
    const focused = useFocused();
    const readOnly = useReadOnly();

    return (
        <PlateElement {...props} className="relative my-4">
            {selected && focused && !readOnly ? <TableToolbar /> : null}
            <div className="overflow-x-auto">
                <table className={tableClassName}>
                    <tbody>{children}</tbody>
                </table>
            </div>
        </PlateElement>
    );
}

export function TableRowElement(props: PlateElementProps): ReactElement {
    return <PlateElement {...props} as="tr" />;
}

function TableCell({
    isHeader,
    ...props
}: PlateElementProps<TTableCellElement> & {
    isHeader?: boolean;
}): ReactElement {
    const { api } = useEditorPlugin(TablePlugin);

    return (
        <PlateElement
            {...props}
            as={isHeader ? 'th' : 'td'}
            attributes={{
                ...props.attributes,
                colSpan: api.table.getColSpan(props.element),
                rowSpan: api.table.getRowSpan(props.element),
            }}
            className={cn(
                tableCellClassName,
                isHeader && 'bg-muted/60 font-medium',
            )}
        />
    );
}

export function TableCellElement(
    props: PlateElementProps<TTableCellElement>,
): ReactElement {
    return <TableCell {...props} />;
}

export function TableCellHeaderElement(
    props: PlateElementProps<TTableCellElement>,
): ReactElement {
    return <TableCell {...props} isHeader />;
}

import { someList, toggleList } from '@platejs/list';
import {
    Bold,
    Code,
    Italic,
    List,
    ListOrdered,
    ListTodo,
    Redo2,
    Strikethrough,
    Underline,
    Undo2,
} from 'lucide-react';
import { KEYS } from 'platejs';
import {
    useEditorRef,
    useEditorSelector,
    useMarkToolbarButton,
    useMarkToolbarButtonState,
} from 'platejs/react';
import type { ReactElement, ReactNode } from 'react';
import { EditorToolbarButton } from '@/components/editor/editor-toolbar';

function MarkButton({
    nodeType,
    label,
    children,
}: {
    nodeType: string;
    label: string;
    children: ReactNode;
}): ReactElement {
    const state = useMarkToolbarButtonState({ nodeType });
    const { props } = useMarkToolbarButton(state);

    return (
        <EditorToolbarButton
            label={label}
            onClick={props.onClick}
            pressed={props.pressed}
        >
            {children}
        </EditorToolbarButton>
    );
}

export function MarkButtons(): ReactElement {
    return (
        <>
            <MarkButton label="Полужирный" nodeType={KEYS.bold}>
                <Bold />
            </MarkButton>
            <MarkButton label="Курсив" nodeType={KEYS.italic}>
                <Italic />
            </MarkButton>
            <MarkButton label="Подчёркнутый" nodeType={KEYS.underline}>
                <Underline />
            </MarkButton>
            <MarkButton label="Зачёркнутый" nodeType={KEYS.strikethrough}>
                <Strikethrough />
            </MarkButton>
            <MarkButton label="Код" nodeType={KEYS.code}>
                <Code />
            </MarkButton>
        </>
    );
}

function ListButton({
    listStyleType,
    label,
    children,
}: {
    listStyleType: string;
    label: string;
    children: ReactNode;
}): ReactElement {
    const editor = useEditorRef();
    const pressed = useEditorSelector(
        (current) => someList(current, listStyleType),
        [listStyleType],
    );

    return (
        <EditorToolbarButton
            label={label}
            onClick={() => {
                toggleList(editor, { listStyleType });
                editor.tf.focus();
            }}
            pressed={pressed}
        >
            {children}
        </EditorToolbarButton>
    );
}

export function ListButtons(): ReactElement {
    return (
        <>
            <ListButton label="Маркированный список" listStyleType={KEYS.ul}>
                <List />
            </ListButton>
            <ListButton label="Нумерованный список" listStyleType={KEYS.ol}>
                <ListOrdered />
            </ListButton>
            <ListButton label="Список задач" listStyleType={KEYS.listTodo}>
                <ListTodo />
            </ListButton>
        </>
    );
}

export function HistoryButtons(): ReactElement {
    const editor = useEditorRef();
    const cannotUndo = useEditorSelector(
        (current) => current.history.undos.length === 0,
        [],
    );
    const cannotRedo = useEditorSelector(
        (current) => current.history.redos.length === 0,
        [],
    );

    return (
        <>
            <EditorToolbarButton
                disabled={cannotUndo}
                label="Отменить"
                onClick={() => editor.undo()}
            >
                <Undo2 />
            </EditorToolbarButton>
            <EditorToolbarButton
                disabled={cannotRedo}
                label="Повторить"
                onClick={() => editor.redo()}
            >
                <Redo2 />
            </EditorToolbarButton>
        </>
    );
}
